package io.aetheris.orchestrator.api;import io.aetheris.orchestrator.career.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/orchestrator/stage8/career") public class RecruiterSimulationController {private final RecruiterSimulationService service;public RecruiterSimulationController(RecruiterSimulationService service){this.service=service;}@PostMapping("/simulate") public RecruiterSimulationResult simulate(@RequestBody RecruiterSimulationRequest r){return service.simulate(r);}@GetMapping("/connectors") public List<Map<String,Object>> connectors(){return service.connectors();}}
